// 7. estimatedCompletionSeconds 존재 여부 ---------------------------------
const creates = rows.filter((row) => row.status === 201);
const withEstimate = creates.filter((row) => row.body && typeof row.body === "object" && "estimatedCompletionSeconds" in (row.body as object));
