    setRetryAttempt(0);
    setRetryBurstStartedAt(null);
    setServerRetryAfterSeconds(null);
    setFailedCycles((n) => n + 1);
  } else {
    setRetryAttempt(nextRetryAttempt);
    setRetryBurstStartedAt(burstStartedAt);
  }
}

